package com.yeyamo_mobile.api.gamification_service.infrastructure.outbox;import java.time.Instant;import java.util.*;import org.springframework.stereotype.Component;import com.fasterxml.jackson.databind.ObjectMapper;import com.yeyamo_mobile.api.gamification_service.application.port.GamificationOutboxPort;
@Component public class JpaGamificationOutboxAdapter implements GamificationOutboxPort{private final GamificationOutboxRepository repo;private final ObjectMapper mapper;public JpaGamificationOutboxAdapter(GamificationOutboxRepository r,ObjectMapper m){repo=r;mapper=m;}public void append(String type,String user,String correlation,Map<String,Object>payload){try{UUID id=UUID.randomUUID();Map<String,Object>event=new LinkedHashMap<>();event.put("eventId",id);event.put("eventType",type);event.put("eventVersion",1);event.put("occurredAt",Instant.now());event.put("producer","gamification-service");event.put("aggregateType","player");event.put("aggregateId",user);event.put("correlationId",correlation==null?id.toString():correlation);event.put("actorId",user);event.put("payload",payload);var e=new GamificationOutboxEvent();e.id=id;e.aggregateId=user;e.eventType=type;e.occurredAt=Instant.now();e.payload=mapper.writeValueAsString(event);repo.save(e);}catch(Exception e){throw new IllegalStateException("Cannot create gamification outbox",e);}}}
